import { useRef, useState } from 'react';

const fields = [
  {
    "name": "Site",
    "v1": "North Hub",
    "v2": "North Hub"
  },
  {
    "name": "Capacity",
    "v1": "12 seats",
    "v2": "18 seats"
  },
  {
    "name": "Start",
    "v1": "04 Jan 2027",
    "v2": "11 Jan 2027"
  }
];
const steps = ["Intake recorded","Finance sign-off","Operations review","Release"];
const gates = [["Verify revised capacity","Confirm start date"],["Attach reviewed version","Confirm release owner"]];

export default function ApprovalStepperChecklist() {
  const [version, setVersion] = useState<'v1' | 'v2'>('v2');
  const [active, setActive] = useState(2);
  const [checked, setChecked] = useState<string[]>([]);
  const [message, setMessage] = useState('');
  const dialog = useRef<HTMLDialogElement>(null);
  const requirements = gates[active - 2] ?? [];
  const ready = requirements.length > 0 && requirements.every(key => checked.includes(key));
  return <section className="grid gap-3 text-start [&_button]:rounded-sm [&_button]:border [&_button]:border-[var(--border-strong)] [&_button]:px-2 [&_button]:py-1 [&_button:disabled]:opacity-50 [&_button[aria-pressed=true]]:bg-[var(--accent-tint)] [&_select]:rounded-sm [&_select]:border [&_input:not([type=checkbox])]:border [&_textarea]:border [&_dialog]:bg-[var(--bg-surface)] [&_dialog]:text-[var(--ink-primary)]">
    <fieldset className="flex flex-wrap gap-2"><legend className="font-semibold">Change record</legend>
      {(['v1', 'v2'] as const).map(v => <button key={v} type="button" aria-pressed={version === v} onClick={() => setVersion(v)}>{v}</button>)}
    </fieldset>
    <dl className="grid gap-1">{fields.map(field =>
      <div key={field.name} className="flex flex-wrap gap-2 border-b py-1"><dt className="font-semibold">{field.name}</dt>
        <dd>{version === 'v2' && field.v1 !== field.v2 && <><del>{field.v1}</del> → </>}{field[version]}</dd></div>)}</dl>
    <ol className="grid gap-2 border-s ps-3">{steps.map((step,i) => {
      const state = i === 1 ? '– Skipped' : i < active ? '✓ Complete' : i === active ? '→ Current' : '○ Waiting';
      return <li key={step} className="grid gap-1"><strong>{step}</strong>
        <span className={'w-fit rounded-sm border px-1 text-xs ' + (i === 1 ? 'border-dashed' : i === active ? 'font-bold' : '')}>{state}</span>
        {i === 1 && <small>Budget unchanged between versions.</small>}</li>;
    })}</ol>
    {active < 4 ? <button type="button" onClick={() => { setChecked([]); dialog.current?.showModal(); }}>Open checklist: {steps[active]}</button>
      : <p className="font-semibold">Release approved</p>}
    <p role="status">{message}</p>
    <dialog ref={dialog} aria-label="Approval checklist" className="max-w-full rounded-sm border p-4"
      onClick={e => { if (e.target === e.currentTarget) dialog.current?.close(); }}>
      <form className="grid gap-2" onSubmit={e => {
        e.preventDefault();
        if (!ready) return;
        setMessage(steps[active] + ' completed for v2.');
        setActive(active + 1);
        dialog.current?.close();
      }}>
        <strong>{steps[active]}</strong>{requirements.map(key => <label key={key}>
          <input type="checkbox" checked={checked.includes(key)} onChange={() =>
            setChecked(items => items.includes(key) ? items.filter(item => item !== key) : [...items,key])} /> {key}
        </label>)}
        <p>{checked.length} / 2 requirements met</p><button type="submit" disabled={!ready}>Approve step</button>
        <button type="button" onClick={() => dialog.current?.close()}>Cancel</button>
      </form>
    </dialog>
  </section>;
}
